package root

import (
	"fmt"
	"strings"

	"github.com/stigmer/stigmer/client-apps/cli/pkg/executiontui"
	"github.com/stigmer/stigmer/client-apps/cli/pkg/termctl"
	"github.com/stigmer/stigmer/client-apps/cli/pkg/toolrender"
)

// initPreApprovalStreaming starts the typewriter streaming mode for a
// write/edit tool whose content is being generated by the AI.
//
// Bubbletea path (program != nil): commits the header to scrollback via
// writeToScrollback then sends streamingShowMsg to activate progressive
// mode. Committing the header renderer-side avoids a race where tea.Println
// Cmds execute in goroutines that can be overtaken by subsequent
// streamingUpdateMsg messages, causing tool content to appear above the
// header.
//
// Direct-write path (program == nil): prints the header and separator
// directly to stderr, then sets row-tracking state for EraseLines.
//
// When the tool's primary arg (e.g. file path) is not yet available in
// Args, header rendering is deferred to the first ToolStreamDeltaEvent.
func (r *inlineRenderer) initPreApprovalStreaming(e executiontui.ToolRunningEvent) {
	r.finishAIStreamIfNeeded()
	r.flushPendingReads()

	r.activeStreamToolID = e.ToolCallID
	r.toolStreamedBytes = 0
	r.streamSubAgentID = e.SubAgentID
	r.streamIsPreApproval = true

	if !toolrender.HasPrimaryArg(e.ToolCall) {
		r.streamHeaderDeferred = true
		r.lastStreamHeader = ""
		if r.cfg.program == nil {
			r.streamHeaderRows = 0
			r.streamLineCount = 0
		}
		return
	}

	header := r.buildStreamHeaderOutput(e.ToolCall)
	r.lastStreamHeader = header

	if r.cfg.program != nil {
		r.commitStreamHeader(header, e.SubAgentID)
		r.cfg.program.Send(streamingShowMsg{
			subAgentID:  e.SubAgentID,
			progressive: true,
		})
		return
	}

	r.renderStreamHeader(e.ToolCall, e.SubAgentID)
}

// buildStreamHeaderOutput returns the pre-approval separator + header
// string without gutter-wrapping. Used by the Bubbletea path to
// populate streamingShowMsg; formatStreamingView applies gutter-wrapping.
func (r *inlineRenderer) buildStreamHeaderOutput(tc toolrender.ToolCallInfo) string {
	width := termctl.Width(r.cfg.status, 80)
	sep := toolrender.ApprovalSeparator(width)
	header := toolrender.ExpandedApprovalHeader(tc, r.compactOpts)
	return sep + "\n" + header + "\n"
}

// commitStreamHeader commits a pre-approval streaming header to
// terminal scrollback via writeToScrollback. Each line is written as
// kindText so that transition-aware gap logic applies consistently.
func (r *inlineRenderer) commitStreamHeader(header, subAgentID string) {
	headerText := strings.TrimRight(header, "\n")
	if subAgentID != "" {
		headerText = toolrender.GutterWrap(headerText)
	}
	for _, line := range strings.Split(headerText, "\n") {
		r.writeToScrollback(kindText, line)
	}
}

// renderStreamHeader prints the pre-approval separator and header for
// a streaming write/edit tool directly to stderr, and updates the
// row-tracking state. Used only by the direct-write fallback path.
func (r *inlineRenderer) renderStreamHeader(tc toolrender.ToolCallInfo, subAgentID string) {
	width := termctl.Width(r.cfg.status, 80)
	sep := toolrender.ApprovalSeparator(width)
	header := toolrender.ExpandedApprovalHeader(tc, r.compactOpts)
	output := sep + "\n" + header + "\n"

	if subAgentID != "" {
		output = toolrender.GutterWrap(output)
	}
	fmt.Fprint(r.cfg.status, output)
	r.flushWriter(r.cfg.status)

	r.streamHeaderRows = termctl.DisplayRows(output, width)
	r.streamLineCount = r.streamHeaderRows
}

// initPostApprovalStreaming starts the live output streaming mode for a
// shell tool that the user just approved.
//
// Bubbletea path: sends streamingShowMsg with the compact running header.
// Direct-write path: prints the header to stderr and sets row-tracking.
func (r *inlineRenderer) initPostApprovalStreaming(toolCallID string, tc toolrender.ToolCallInfo, subAgentID string) {
	r.activeStreamToolID = toolCallID
	r.toolStreamedBytes = 0
	r.streamSubAgentID = subAgentID

	header := toolrender.RenderCompactRunning(tc, r.compactOpts)

	if r.cfg.program != nil {
		r.cfg.program.Send(streamingShowMsg{
			header:      header + "\n",
			subAgentID:  subAgentID,
			progressive: false,
		})
		return
	}

	if subAgentID != "" {
		header = toolrender.GutterWrap(header)
	}
	r.statusf("%s\n", header)

	width := termctl.Width(r.cfg.status, 80)
	r.streamHeaderRows = termctl.DisplayRows(header+"\n", width)
	r.streamLineCount = r.streamHeaderRows
}

// renderToolStreamDelta processes a content delta from a streaming tool.
//
// Bubbletea path: resolves the full content and sends streamingUpdateMsg.
// View() handles formatting (width-clamping, line-capping, truncation).
// If the header was deferred, streamingShowMsg is sent first.
//
// Direct-write path: prints only new bytes (delta rendering) with
// width-clamping and line-capping enforced incrementally.
func (r *inlineRenderer) renderToolStreamDelta(e executiontui.ToolStreamDeltaEvent) {
	if r.streamHeaderDeferred {
		r.streamHeaderDeferred = false
		header := r.buildStreamHeaderOutput(e.ToolCall)
		r.lastStreamHeader = header
		if r.cfg.program != nil {
			r.commitStreamHeader(header, r.streamSubAgentID)
			r.cfg.program.Send(streamingShowMsg{
				subAgentID:  r.streamSubAgentID,
				progressive: true,
			})
		} else {
			r.renderStreamHeader(e.ToolCall, r.streamSubAgentID)
		}
	} else if r.cfg.program != nil && r.lastStreamHeader != "" {
		newHeader := r.buildStreamHeaderOutput(e.ToolCall)
		if newHeader != r.lastStreamHeader {
			r.lastStreamHeader = newHeader
			r.cfg.program.Send(streamingHeaderUpdateMsg{header: newHeader})
		}
	}

	content := resolveStreamContent(e)
	if len(content) <= r.toolStreamedBytes {
		return
	}

	if r.cfg.program != nil {
		r.toolStreamedBytes = len(content)
		r.cfg.program.Send(streamingUpdateMsg{content: content})
		return
	}

	r.renderToolStreamDeltaDirect(content)
}

// renderToolStreamDeltaDirect is the direct-write implementation of delta
// rendering. Only bytes beyond toolStreamedBytes are printed. Both
// pre-approval and post-approval streaming flow uncapped — every line is
// printed as it arrives.
func (r *inlineRenderer) renderToolStreamDeltaDirect(content string) {
	newBytes := content[r.toolStreamedBytes:]
	r.toolStreamedBytes = len(content)
	r.renderStreamDeltaUncapped(content, newBytes)
}

// renderStreamDeltaUncapped handles post-approval streaming where no
// line capping is needed. Prints the new bytes directly and updates
// the row count for EraseLines.
func (r *inlineRenderer) renderStreamDeltaUncapped(content, newBytes string) {
	output := newBytes
	if r.streamSubAgentID != "" {
		output = toolrender.GutterWrap(output)
	}
	fmt.Fprint(r.cfg.status, output)
	r.flushWriter(r.cfg.status)

	width := termctl.Width(r.cfg.status, 80)
	displayContent := content
	if r.streamSubAgentID != "" {
		displayContent = toolrender.GutterWrap(content)
	}
	r.streamLineCount = r.streamHeaderRows + termctl.DisplayRows(displayContent, width)
}

// completeStreamingTool handles ToolCompletedEvent for a tool that was
// streaming output.
//
// Bubbletea path: records the compact result in history, clears streaming
// state, and triggers a re-commit. The re-commit atomically replaces any
// progressively-committed scrollback content with the authoritative
// history, ensuring no stale streaming lines remain.
//
// Direct-write path: erases the streaming content via EraseLines, then
// prints the final compact result via commitToScrollback (which appends
// to history and renders with unified spacing).
func (r *inlineRenderer) completeStreamingTool(e executiontui.ToolCompletedEvent) {
	subAgentID := r.streamSubAgentID
	item := committedItem{
		kind:       kindToolCompact,
		toolCalls:  []toolrender.ToolCallInfo{e.ToolCall},
		subAgentID: subAgentID,
	}

	if r.hasActiveSubAgent(subAgentID) {
		r.appendToSubAgentBlock(subAgentID, item, true)
		r.clearStreamingState()
		if r.cfg.program != nil {
			r.triggerReCommit()
		}
		return
	}

	if r.cfg.program != nil {
		r.recordToHistory(item)
		r.clearStreamingState()
		r.triggerReCommit()
	} else {
		if termctl.IsSupported(r.cfg.status) && r.streamLineCount > 0 {
			termctl.EraseLines(r.cfg.status, r.streamLineCount)
		}
		r.clearStreamingState()
		r.commitToScrollback(item)
	}
}

// clearStreamingState resets all streaming tracking fields to their
// zero values. Called after streaming completes — either by
// completeStreamingTool (post-approval) or renderToolWaitingApproval
// (pre-approval transition to approval flow).
func (r *inlineRenderer) clearStreamingState() {
	r.activeStreamToolID = ""
	r.toolStreamedBytes = 0
	r.streamHeaderRows = 0
	r.streamLineCount = 0
	r.streamSubAgentID = ""
	r.streamHeaderDeferred = false
	r.lastStreamHeader = ""
	r.streamIsPreApproval = false
}

// resolveStreamContent extracts the displayable content from a
// ToolStreamDeltaEvent. Prefers e.Content (shell output, generic
// streaming). Falls back to ExpandedApprovalContent for write/edit
// tools where content lives in Args rather than the Content field.
func resolveStreamContent(e executiontui.ToolStreamDeltaEvent) string {
	if e.Content != "" {
		return e.Content
	}
	return toolrender.ExpandedApprovalContent(e.ToolCall)
}

